{
  "technical_and_design_decisions": [
    "Add the spring-boot-starter-security dependency to the spring-xd-dirt module and rely on Spring Boot 1.1.x autoconfiguration (SecurityAutoConfiguration) to enforce HTTP Basic Auth on the XD admin REST endpoints when enabled.",
    "Gate the security autoconfiguration behind the Spring Boot property server.basic.enabled, with the default set to false in application.yml so unsecured behavior remains the out-of-box default.",
    "Implement single-user security by exposing Spring Boot's SecurityProperties (security.user.name, security.user.password, security.user.role) through the existing servers.yml configuration file, allowing operators to override defaults without code changes.",
    "Extend the XD Shell 'admin config' command with --username and --password options, persist them in the shell session state, and inject an HTTP Basic Authorization header into all admin REST calls via a RestTemplate ClientHttpRequestInterceptor.",
    "Consume the latest Spring Boot SNAPSHOT via the Spring snapshot repository (repo.spring.io/snapshot) in the Gradle build for U4, then switch the dependency to the Spring Boot RELEASE version and remove/retain snapshot repositories as appropriate for U5.",
    "Build both Docker images from an Ubuntu base image with Java 7 installed; the sandbox image additionally installs and co-locates Redis and RabbitMQ started by a lightweight supervisor/startup script alongside the full XD runtime.",
    "Design the production-ready image to run only the full XD jar, with Redis/RabbitMQ (transport and analytics backends) treated as external services configured via environment variables or mounted configuration.",
    "Treat U6 strictly as a spike: the deliverable is an options/assessment document, team feedback, phased breakdown, and newly created stories - no production code."
  ],
  "assumptions": [
    "The codebase is Spring XD (spring-xd-dirt and spring-xd-shell modules) built with Gradle and targeting Java 7, consistent with the Spring Boot 1.1.x era referenced in the specification.",
    "Spring Boot 1.1.x provides out-of-the-box basic authentication and single-user security properties, so no custom authentication provider or user store needs to be implemented.",
    "servers.yml is already loaded by the XD bootstrap and only needs new security keys bound into the environment; no new configuration file mechanism is required.",
    "The XD Shell communicates with the admin server over REST, so basic auth can be added entirely client-side by setting the Authorization header.",
    "Docker and a suitable base image registry are available on the developer machine; effort covers authoring Dockerfiles, building, and locally running/testing images, but not publishing to a corporate registry or setting up CI/CD pipelines.",
    "A single developer performs all work including unit tests, integration tests, documentation, and self-review; peer code review and merge overhead by other team members is excluded.",
    "Upgrading to the Spring Boot SNAPSHOT (U4) may require minor code adjustments due to upstream API changes; upgrading to the RELEASE (U5) is expected to be more stable and therefore less effort.",
    "Existing XD test infrastructure (JUnit, integration test harness) can be reused for the new security tests without modification.",
    "U7's sandbox image runs Redis, RabbitMQ, and XD in a single container purely for experimentation; no clustering, persistence volumes, or production hardening is required for it.",
    "Effort is measured in work-hours of one developer and excludes elapsed-time factors such as waiting on snapshot publication, team feedback cycles, or image download times."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Environment setup and baseline build verification",
      "activity_description": "Check out the spring-xd repository, verify the current Gradle build passes with Java 7, set up the snapshot/release Maven repositories, and confirm a working Docker environment for the image work.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2",
      "activity_name": "U4 - Upgrade build to latest Spring Boot SNAPSHOT",
      "activity_description": "Update build.gradle/buildscript configuration to pull the latest Spring Boot 1.1.x SNAPSHOT from repo.spring.io/snapshot, resolve resulting compilation errors, dependency conflicts, and API changes, and verify a green build with existing tests.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "U5 - Upgrade build to Spring Boot RELEASE",
      "activity_description": "Switch the Spring Boot dependency from SNAPSHOT to the RELEASE version, adjust repository configuration, resolve any remaining incompatibilities, and re-run the full build and regression test suite.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 - Enable optional Basic Auth via Spring Boot Security",
      "activity_description": "Add the spring-boot-starter-security dependency to spring-xd-dirt, wire basic auth so it is active only when server.basic.enabled=true, add the property with default false to application.yml, and write unit/integration tests verifying both the challenged (401/401-then-200) and unchallenged modes.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 - Single-user security configuration via servers.yml",
      "activity_description": "Expose single-user credentials (username, password, role) through servers.yml by binding Spring Boot SecurityProperties into the XD environment, implement default and override handling, add tests for override scenarios, and document the configuration keys.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A6",
      "activity_name": "U3 - XD Shell basic auth credentials support",
      "activity_description": "Add --username and --password options to the shell's 'admin config' command, persist them in shell state, inject an HTTP Basic Authorization header into all admin REST requests via a RestTemplate interceptor, handle 401 responses gracefully, and add shell-side tests plus help/documentation updates.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "End-to-end security integration testing",
      "activity_description": "Perform cross-component verification: start a secured XD admin server, connect from the XD Shell with valid and invalid credentials, verify rejection without credentials and acceptance with correct credentials, and run negative/edge-case tests (empty password, special characters).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "U6 - Spike: REST API for uploading module archives",
      "activity_description": "Assess the customer requirement for point-and-push upload of archives containing custom module definitions and configurations, brainstorm and document design options, socialize the options with the team and incorporate feedback, identify implementation phases, and author the follow-on stories. No production code is delivered.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "U7 - Sandbox Docker image (Ubuntu, Java 7, Redis, RabbitMQ, full XD jar)",
      "activity_description": "Author a Dockerfile based on Ubuntu that installs Java 7, Redis, and RabbitMQ, bundles the full XD jar, and provides a startup/supervisor script that launches all services and XD together; build the image, run it, verify XD operates against the in-container Redis/RabbitMQ, and write usage documentation.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A10",
      "activity_name": "U8 - Production-ready Docker image (Ubuntu, Java 7, full XD jar)",
      "activity_description": "Author a leaner production-baseline Dockerfile based on Ubuntu with Java 7 and the full XD jar only, externalize transport/analytics configuration (Redis/RabbitMQ endpoints) via environment variables or mounted config, apply basic hardening (non-root user, minimal packages), build and test the image against external services, and document deployment usage.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation and release notes",
      "activity_description": "Update project documentation covering enabling basic auth, servers.yml security overrides, shell credential usage, and both Docker images; draft concise release notes for the increment.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 120
  }
}

